# Exact level-1 (and level-2) root scan for nonsingular equations with 2x2 rational constants.
# A root of w(x; a) = 1 exists over an algebraic closure of Q iff 1 is not in the ideal
# generated by the entries of w(T; a) - 1 and z*det(T) - 1 (weak Nullstellensatz).
import sys, time
from sage.all import QQ, PolynomialRing, matrix, identity_matrix, alarm, cancel_alarm
from cysignals.signals import AlarmInterrupt

MAXLEN = int(sys.argv[1]) if len(sys.argv) > 1 else 7
LEVEL2_MAX = int(sys.argv[2]) if len(sys.argv) > 2 else 12
LETTERS = ['a', 'A', 'b', 'B', 'x', 'X']
INV = {'a': 'A', 'A': 'a', 'b': 'B', 'B': 'b', 'x': 'X', 'X': 'x'}


def words(maxlen):
    out = set()
    stack = ['']
    while stack:
        w = stack.pop()
        if w and w.count('x') - w.count('X') == 1 and 'X' in w and INV[w[0]] != w[-1]:
            out.add(min(w[i:] + w[:i] for i in range(len(w))))
        if len(w) < maxlen:
            for c in LETTERS:
                if not w or INV[c] != w[-1]:
                    stack.append(w + c)
    return sorted(out, key=lambda s: (len(s), s))


def M(rows):
    return matrix(QQ, rows)


TUPLES = {
    'control_dihedral8': (M([[0, 1], [1, 0]]), M([[1, 0], [0, -1]])),
    'control_trivial': (M([[1, 0], [0, 1]]), M([[1, 0], [0, 1]])),
    'bs12_affine': (M([[2, 0], [0, 1]]), M([[1, 1], [0, 1]])),
    'sl2z_unipotents': (M([[1, 1], [0, 1]]), M([[1, 0], [1, 1]])),
    'reflections_hyperbolic_product': (M([[1, 0], [0, -1]]), M([[3, -4], [2, -3]])),
    'diag2_lower_unipotent': (M([[2, 0], [0, 1]]), M([[1, 0], [1, 1]])),
    'cat_map_unipotent': (M([[2, 1], [1, 1]]), M([[1, 1], [0, 1]])),
    'generic_rational': (M([[2, 3], [5, 7]]), M([[1, 4], [2, -1]])),
}


def build(level):
    N = 2 * level
    names = ['t%d_%d' % (i, j) for i in range(N) for j in range(N)] + ['y%d_%d' % (i, j) for i in range(N) for j in range(N)]
    R = PolynomialRing(QQ, names, order='degrevlex')
    g = R.gens()
    T = matrix(R, N, N, g[:N * N])
    Y = matrix(R, N, N, g[N * N:])
    return R, T, Y


def evaluate(word, T, Y, a, b, level):
    R = T.base_ring()
    if level == 1:
        ca, cb = a, b
    else:
        I2 = identity_matrix(QQ, level)
        ca, cb = a.tensor_product(I2), b.tensor_product(I2)
    mats = {'x': T, 'X': Y, 'a': matrix(R, ca), 'A': matrix(R, ca.inverse()), 'b': matrix(R, cb), 'B': matrix(R, cb.inverse())}
    W = identity_matrix(R, T.nrows())
    for c in word:
        W = W * mats[c]
    return W


def solvable(word, a, b, level, timeout=None):
    R, T, Y = build(level)
    W = evaluate(word, T, Y, a, b, level)
    N = T.nrows()
    eqs = list((W - identity_matrix(R, N)).list()) + list((T * Y - identity_matrix(R, N)).list())
    I = R.ideal(eqs)
    if timeout:
        alarm(timeout)
    try:
        gb = I.groebner_basis()
    except AlarmInterrupt:
        return None
    finally:
        if timeout:
            cancel_alarm()
    return not (len(gb) == 1 and gb[0] == 1)


def main():
    ws = words(MAXLEN)
    print('MAXLEN', MAXLEN, 'words', len(ws), flush=True)
    for name, (a, b) in TUPLES.items():
        t0 = time.time()
        fails = []
        for w in ws:
            s = solvable(w, a, b, 1)
            if not s:
                fails.append(w)
        print('TUPLE', name, 'level1_unsolvable', len(fails), 'of', len(ws), 'secs', round(time.time() - t0, 1), flush=True)
        for w in fails[:60]:
            print('  L1FAIL', name, w, flush=True)
        for w in fails[:LEVEL2_MAX]:
            s2 = solvable(w, a, b, 2, timeout=900)
            print('  L2', name, w, 'solvable' if s2 else ('TIMEOUT' if s2 is None else 'UNSOLVABLE'), flush=True)
    print('SCAN_DONE', flush=True)


main()
